// emitter.ts
class Emitter {
  mcp;
  store;
  constructor(mcp, store) {
    this.mcp = mcp;
    this.store = store;
  }
  async emit(ev) {
    this.store.enqueuePending(ev.kind, ev.content, ev.meta);
    await this.flushPending();
  }
  async flushPending() {
    const events = this.store.drainPending();
    if (events.length === 0)
      return;
    const delivered = [];
    for (const ev of events) {
      try {
        await this.mcp.notification({
          method: "notifications/claude/channel",
          params: {
            content: ev.content,
            meta: { kind: ev.kind, ...ev.meta }
          }
        });
        delivered.push(ev.id);
      } catch (err) {
        console.error("[lmheads-channel] notification delivery failed:", err);
        break;
      }
    }
    if (delivered.length > 0)
      this.store.markDelivered(delivered);
  }
}

// store.ts
import { Database } from "bun:sqlite";
import { mkdirSync as mkdirSync2 } from "fs";
import { dirname as dirname2 } from "path";

class Store {
  db;
  constructor(dbPath) {
    mkdirSync2(dirname2(dbPath), { recursive: true });
    this.db = new Database(dbPath);
    this.db.exec("PRAGMA journal_mode = WAL");
    this.db.exec("PRAGMA busy_timeout = 5000");
    this.maybeResetLegacySchema();
    this.migrate();
  }
  maybeResetLegacySchema() {
    const legacyMarkers = ["watched_deals", "watched_offers", "seen_posts"];
    for (const name of legacyMarkers) {
      const row = this.db.query(`SELECT name FROM sqlite_master WHERE type='table' AND name='${name}'`).get();
      if (!row)
        continue;
      this.db.exec(`
        DROP TABLE IF EXISTS pending_events;
        DROP TABLE IF EXISTS seen_search_results;
        DROP TABLE IF EXISTS saved_searches;
        DROP TABLE IF EXISTS watched_offers;
        DROP TABLE IF EXISTS watched_deals;
        DROP TABLE IF EXISTS seen_posts;
        DROP TABLE IF EXISTS seen_tasks;
      `);
      return;
    }
  }
  migrate() {
    this.db.exec(`
      CREATE TABLE IF NOT EXISTS seen_tasks (
        task_id    TEXT PRIMARY KEY,
        last_state TEXT NOT NULL,
        last_msg_at TEXT NOT NULL DEFAULT '',
        observed_at TEXT NOT NULL DEFAULT (datetime('now'))
      );

      CREATE TABLE IF NOT EXISTS pending_events (
        id INTEGER PRIMARY KEY AUTOINCREMENT,
        kind TEXT NOT NULL,
        content TEXT NOT NULL,
        meta TEXT NOT NULL,
        created_at TEXT NOT NULL DEFAULT (datetime('now')),
        delivered_at TEXT
      );

      CREATE INDEX IF NOT EXISTS idx_pending_undelivered
        ON pending_events(delivered_at) WHERE delivered_at IS NULL;
    `);
  }
  markTaskSeen(taskId, state, lastMsgAt) {
    const prev = this.db.query("SELECT last_state, last_msg_at FROM seen_tasks WHERE task_id = ?").get(taskId);
    this.db.query(`INSERT INTO seen_tasks (task_id, last_state, last_msg_at) VALUES (?, ?, ?)
         ON CONFLICT(task_id) DO UPDATE SET
           last_state = excluded.last_state,
           last_msg_at = excluded.last_msg_at,
           observed_at = datetime('now')`).run(taskId, state, lastMsgAt);
    return prev ? { state: prev.last_state, lastMsgAt: prev.last_msg_at } : undefined;
  }
  enqueuePending(kind, content, meta) {
    this.db.query(`INSERT INTO pending_events (kind, content, meta) VALUES (?, ?, ?)`).run(kind, content, JSON.stringify(meta));
  }
  drainPending() {
    const rows = this.db.query(`SELECT id, kind, content, meta, created_at, delivered_at
         FROM pending_events
         WHERE delivered_at IS NULL
         ORDER BY id ASC`).all();
    return rows.map((r2) => ({ ...r2, meta: safeParseMeta(r2.meta) }));
  }
  markDelivered(ids) {
    if (ids.length === 0)
      return;
    const placeholders = ids.map(() => "?").join(",");
    this.db.query(`UPDATE pending_events SET delivered_at = datetime('now') WHERE id IN (${placeholders})`).run(...ids);
  }
  countPending() {
    const row = this.db.query("SELECT COUNT(*) AS n FROM pending_events WHERE delivered_at IS NULL").get();
    return row?.n ?? 0;
  }
  close() {
    this.db.close();
  }
}
function safeParseMeta(raw) {
  try {
    const parsed = JSON.parse(raw);
    if (parsed && typeof parsed === "object" && !Array.isArray(parsed)) {
      const out = {};
      for (const [k2, v2] of Object.entries(parsed))
        out[k2] = String(v2);
      return out;
    }
  } catch {}
  return {};
}

// events.ts
function taskRequestReceivedEvent(task) {
  const firstUserMsg = (task.messages ?? []).find((m2) => m2.role === "user");
  const summary = summarizeMessage(firstUserMsg);
  return {
    kind: "task_request_received",
    content: `New task on agent ${task.callee_agent_id} \u2014 skill "${task.skill}" from ${task.caller_agent_id}.` + (summary ? ` ${summary}` : ""),
    meta: {
      task_id: task.id,
      caller_agent_id: task.caller_agent_id,
      callee_agent_id: task.callee_agent_id,
      skill: task.skill,
      state: task.state
    }
  };
}
function taskMessageReceivedEvent(task, message, role = "callee") {
  const counter = role === "caller" ? task.callee_agent_name || task.callee_agent_id.slice(0, 8) : task.caller_agent_name || task.caller_agent_id.slice(0, 8);
  const summary = summarizeMessage(message);
  const content = role === "caller" ? `Update on your outbound task ${task.id.slice(0, 8)} (${task.skill}) \u2014 ${counter} says: ${summary}` : `New message on task ${task.id.slice(0, 8)} (${task.skill}) from ${counter}: ${summary}`;
  return {
    kind: "task_message_received",
    content,
    meta: {
      task_id: task.id,
      role: message.role,
      state: task.state,
      participant_role: role
    }
  };
}
function taskStateChangedEvent(task, role = "callee") {
  const counter = role === "caller" ? task.callee_agent_name || task.callee_agent_id.slice(0, 8) : task.caller_agent_name || task.caller_agent_id.slice(0, 8);
  const content = role === "caller" ? `Outbound task ${task.id.slice(0, 8)} (${task.skill}) \u2192 ${task.state} (callee: ${counter})` : `Task ${task.id.slice(0, 8)} (${task.skill}) \u2192 ${task.state}`;
  return {
    kind: "task_state_changed",
    content,
    meta: {
      task_id: task.id,
      state: task.state,
      skill: task.skill,
      participant_role: role
    }
  };
}
function digestEvent(count) {
  return {
    kind: "digest",
    content: `${count} pending lmheads event${count === 1 ? "" : "s"} accumulated while no session was active. Reading them now.`,
    meta: { count: String(count) }
  };
}
function errorEvent(message) {
  return {
    kind: "error",
    content: `lmheads channel error: ${message}`,
    meta: {}
  };
}
function summarizeMessage(m2) {
  if (!m2)
    return "";
  for (const p2 of m2.parts) {
    if (p2.kind === "text" && p2.text)
      return p2.text.slice(0, 200);
    if (p2.kind === "data")
      return JSON.stringify(p2.data).slice(0, 200);
    if (p2.kind === "file")
      return `[file ${p2.filename ?? p2.url ?? "?"}]`;
  }
  return "";
}

