class Streamer {
  api;
  store;
  emit;
  baseUrl;
  apiKey;
  stopped = false;
  agentControllers = new Map;
  retryMs = new Map;
  refreshTimer = null;
  constructor(api2, store, emit, baseUrl, apiKey) {
    this.api = api2;
    this.store = store;
    this.emit = emit;
    this.baseUrl = baseUrl;
    this.apiKey = apiKey;
  }
  start() {
    this.bootstrap();
  }
  stop() {
    this.stopped = true;
    for (const c2 of this.agentControllers.values())
      c2.abort();
    this.agentControllers.clear();
    if (this.refreshTimer)
      clearTimeout(this.refreshTimer);
  }
  async bootstrap() {
    const pendingCount = this.store.countPending();
    if (pendingCount > 0) {
      await this.emit.emit(digestEvent(pendingCount));
    } else {
      await this.emit.flushPending();
    }
    await this.refreshAgents();
  }
  async refreshAgents() {
    if (this.stopped)
      return;
    try {
      const agents = await this.api.myAgents();
      for (const a2 of agents) {
        if (!this.agentControllers.has(a2.id)) {
          this.openStream(a2.id);
        }
      }
    } catch (err) {
      const msg = err instanceof Error ? err.message : String(err);
      console.error("[lmheads-channel] list agents failed:", msg);
    }
    this.refreshTimer = setTimeout(() => void this.refreshAgents(), 5 * 60 * 1000);
  }
  openStream(agentId) {
    if (this.stopped)
      return;
    const ctrl = new AbortController;
    this.agentControllers.set(agentId, ctrl);
    this.runStream(agentId, ctrl).then(() => {
      this.agentControllers.delete(agentId);
      this.scheduleReconnect(agentId);
    });
  }
  scheduleReconnect(agentId) {
    if (this.stopped)
      return;
    const prev = this.retryMs.get(agentId) ?? 1000;
    const next = Math.min(prev * 2, 30000);
    this.retryMs.set(agentId, next);
    setTimeout(() => this.openStream(agentId), prev);
  }
  async runStream(agentId, ctrl) {
    const url = `${this.baseUrl.replace(/\/$/, "")}/api/v1/a2a/agents/${encodeURIComponent(agentId)}/events`;
    let res;
    try {
      res = await fetch(url, {
        method: "GET",
        headers: {
          Authorization: `Bearer ${this.apiKey}`,
          Accept: "text/event-stream"
        },
        signal: ctrl.signal
      });
    } catch (err) {
      if (!ctrl.signal.aborted) {
        const msg = err instanceof Error ? err.message : String(err);
        console.error(`[lmheads-channel] stream connect failed for ${agentId}:`, msg);
      }
      return;
    }
    if (!res.ok || !res.body) {
      console.error(`[lmheads-channel] stream ${agentId} returned ${res.status}`);
      return;
    }
    this.retryMs.set(agentId, 1000);
    const reader = res.body.getReader();
    const decoder = new TextDecoder("utf-8");
    let buf = "";
    try {
      while (!ctrl.signal.aborted) {
        const { value, done } = await reader.read();
        if (done)
          break;
        buf += decoder.decode(value, { stream: true });
        let idx;
        while ((idx = buf.indexOf(`

`)) >= 0) {
          const frame = buf.slice(0, idx);
          buf = buf.slice(idx + 2);
          await this.handleFrame(frame, agentId);
        }
      }
    } catch (err) {
      if (!ctrl.signal.aborted) {
        const msg = err instanceof Error ? err.message : String(err);
        console.error(`[lmheads-channel] stream ${agentId} read err:`, msg);
        await this.emit.emit(errorEvent(msg)).catch(() => {});
      }
    }
  }
  async handleFrame(frame, agentId) {
    const lines = frame.split(`
`);
    const dataLines = [];
    for (const line of lines) {
      if (line.startsWith(":"))
        continue;
      if (line.startsWith("data:"))
        dataLines.push(line.slice(5).trimStart());
    }
    if (dataLines.length === 0)
      return;
    const data = dataLines.join(`
`);
    let ev;
    try {
      ev = JSON.parse(data);
    } catch {
      return;
    }
    await this.dispatch(ev, agentId);
  }
  async dispatch(ev, agentId) {
    switch (ev.kind) {
      case "snapshot":
        for (const t2 of ev.tasks ?? []) {
          this.store.markTaskSeen(t2.id, t2.state, t2.updated_at ?? "");
        }
        return;
      case "task.created": {
        const task = synthesizeTask(ev, agentId);
        const prev = this.store.markTaskSeen(task.id, task.state, task.updated_at);
        if (prev)
          return;
        await this.emit.emit(taskRequestReceivedEvent(task));
        return;
      }
      case "task.update": {
        const task = synthesizeTask(ev, agentId);
        const prev = this.store.markTaskSeen(task.id, task.state, task.updated_at);
        const isCaller = ev.caller_agent_id === agentId;
        if (!prev || prev.state !== task.state) {
          await this.emit.emit(taskStateChangedEvent(task, isCaller ? "caller" : "callee"));
        }
        if (ev.message) {
          await this.emit.emit(taskMessageReceivedEvent(task, normalizeMessage(ev.message, task.id), isCaller ? "caller" : "callee"));
        }
        return;
      }
      case "task.expired": {
        const task = synthesizeTask(ev, agentId);
        this.store.markTaskSeen(task.id, task.state, task.updated_at);
        const isCaller = ev.caller_agent_id === agentId;
        await this.emit.emit(taskStateChangedEvent(task, isCaller ? "caller" : "callee"));
        return;
      }
      default:
        return;
    }
  }
}
function synthesizeTask(ev, agentId) {
  const now = ev.at ?? new Date().toISOString();
  const messages = ev.message ? [normalizeMessage(ev.message, ev.task_id ?? "")] : [];
  return {
    id: ev.task_id ?? "",
    context_id: "",
    caller_agent_id: ev.caller_agent_id ?? "",
    callee_agent_id: agentId,
    skill: ev.skill ?? "",
    state: ev.state ?? "submitted",
    delegation_depth: 0,
    created_at: now,
    updated_at: now,
    messages
  };
}
function normalizeMessage(m2, fallbackTaskId) {
  const parts = (m2.parts ?? []).map((p2) => ({
    kind: p2.kind === "text" || p2.kind === "data" || p2.kind === "file" ? p2.kind : "text",
    text: p2.text
  }));
  return {
    id: m2.messageId ?? "",
    task_id: m2.taskId ?? fallbackTaskId,
    role: m2.role === "agent" ? "agent" : "user",
    parts,
    created_at: new Date().toISOString()
  };
}
